{
  "status": "plan",
  "steps": [
    {
      "op": "aggregate",
      "input": "roasts",
      "as": "agg1",
      "group_by": ["origin"],
      "metrics": [
        {
          "as": "avg_score",
          "fn": "mean",
          "column": "cupping"
        }
      ]
    },
    {
      "op": "derive",
      "input": "agg1",
      "as": "rounded",
      "column": "avg_score",
      "expr": "round(avg_score, digits=1) if not is_null(avg_score) else null"
    },
    {
      "op": "sort",
      "input": "rounded",
      "as": "sorted",
      "by": [
        {
          "column": "avg_score",
          "order": "desc"
        }
      ]
    },
    {
      "op": "select",
      "input": "sorted",
      "as": "final",
      "columns": ["origin", "avg_score"]
    }
  ]
}

