{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "scores",
      "as": "with_totals",
      "column": "total",
      "expr": "coalesce(innovation, 0) + coalesce(execution, 0) + coalesce(polish, 0)"
    },
    {
      "op": "derive",
      "input": "with_totals",
      "as": "with_counts",
      "column": "cnt",
      "expr": "(0 if is_null(innovation) else 1) + (0 if is_null(execution) else 1) + (0 if is_null(polish) else 1)"
    },
    {
      "op": "aggregate",
      "input": "with_counts",
      "as": "by_judge",
      "group_by": ["judge"],
      "metrics": [
        {
          "as": "total_sum",
          "fn": "sum",
          "column": "total"
        },
        {
          "as": "cnt_sum",
          "fn": "sum",
          "column": "cnt"
        }
      ]
    },
    {
      "op": "derive",
      "input": "by_judge",
      "as": "with_avg",
      "column": "avg_mark",
      "expr": "round(total_sum / cnt_sum, 1)"
    },
    {
      "op": "select",
      "input": "with_avg",
      "as": "result",
      "columns": ["judge", "avg_mark"]
    }
  ]
}

